using System.Collections.Generic;using UnityEngine;
namespace Kamilunavo.PerfectDrop.Visuals {
 public static class TerraceArtGeometry {
  // A rounded solid perimeter, shared by every live slab and narrow cut.
  public static Mesh RoundedInset()=>RoundedInsetGeometry().Mesh("PerfectDropRoundedInset");
  public static Buffer RoundedInsetGeometry(){var buffer=new Buffer();const int steps=32;for(int i=0;i<steps;i++){float a=i*Mathf.PI*2/steps,b=(i+1)*Mathf.PI*2/steps;Vector3 A=Rounded(a,.425f),B=Rounded(b,.425f),C=Rounded(b,.412f),D=Rounded(a,.412f);buffer.Quad(A+Vector3.up*.5f,B+Vector3.up*.5f,C+Vector3.up*.5f,D+Vector3.up*.5f,Vector3.up);buffer.Quad(D-Vector3.up*.5f,C-Vector3.up*.5f,B-Vector3.up*.5f,A-Vector3.up*.5f,Vector3.down);buffer.Quad(A-Vector3.up*.5f,B-Vector3.up*.5f,B+Vector3.up*.5f,A+Vector3.up*.5f,new Vector3(A.x,0,A.z));buffer.Quad(C-Vector3.up*.5f,D-Vector3.up*.5f,D+Vector3.up*.5f,C+Vector3.up*.5f,new Vector3(-C.x,0,-C.z));}return buffer;}
  static Vector3 Rounded(float angle,float extent){float c=Mathf.Cos(angle),s=Mathf.Sin(angle);return new Vector3(Mathf.Sign(c)*Mathf.Pow(Mathf.Abs(c),.24f)*extent,0,Mathf.Sign(s)*Mathf.Pow(Mathf.Abs(s),.24f)*extent);}
  public static void Build(Transform dais){var owner=dais.gameObject.AddComponent<TerraceArtOwner>();
   Material stone=Material(owner,"TerraceIvoryStone",new Color(.76f,.68f,.54f),.06f,.34f),brass=Material(owner,"TerraceAgedBrass",new Color(.70f,.43f,.16f),.68f,.64f),leaf=Material(owner,"TerraceCypress",new Color(.16f,.26f,.15f),.0f,.18f),dark=Material(owner,"TerraceArchShadow",new Color(.075f,.11f,.17f),.15f,.43f);
   var foundation=new Buffer();foundation.Lathe(new Vector3(0,0,0),new[]{-3.35f,-3.14f,-2.98f,-1.38f,-1.13f,-1.08f},new[]{2.45f,3.17f,3.26f,3.13f,3.25f,3.25f},48);foundation.Upload(dais,"TerraceFoundation",stone,owner);
   var foreLeaf=new Buffer();var paving=new Buffer();paving.Lathe(Vector3.zero,new[]{-3.47f,-3.32f,-3.27f},new[]{6.2f,6.2f,6.12f},48);
   // A broad grounded forecourt and masonry steps give the dais structural scale.
   for(int step=0;step<5;step++)paving.Box(new Vector3(0,-1.30f-step*.42f,-3.15f-step*.41f),new Vector3(2.7f,.26f,.84f));
   var detailing=new Buffer();detailing.Ring(Vector3.up*-1.12f,3.25f,.04f,48);detailing.Ring(Vector3.up*-2.83f,3.23f,.035f,48);detailing.Ring(Vector3.up*-3.26f,5.82f,.045f,48);
   for(int side=-1;side<=1;side+=2)for(int end=-1;end<=1;end+=2){var point=new Vector3(side*4.55f,-3.2f,end*4.55f);Lantern(paving,detailing,point);Cypress(foreLeaf,point+new Vector3(side*.85f,0,0));}
   for(int side=-1;side<=1;side+=2){Marker(dais,"TerraceBalustrade");for(int post=0;post<9;post++)paving.Box(new Vector3(side*5.5f,-2.76f,-4.5f+post*1.12f),new Vector3(.16f,.90f,.16f));paving.Box(new Vector3(side*5.5f,-2.25f,0),new Vector3(.30f,.18f,9.5f));}
   paving.Upload(dais,"TerraceForecourt",stone,owner);foreLeaf.Upload(dais,"TerraceForecourtGarden",leaf,owner);detailing.Upload(dais,"TerracePedestalBrass",brass,owner);
   var world=new GameObject("TerraceWorld").transform;world.SetParent(dais,false);var themes=new Transform[3];
   for(int chapter=0;chapter<3;chapter++){var theme=new GameObject("Theme"+chapter).transform;theme.SetParent(world,false);themes[chapter]=theme;
    var masonry=Material(owner,"TerraceThemeStone"+chapter,chapter==0?new Color(.84f,.78f,.66f):chapter==1?new Color(.66f,.46f,.30f):new Color(.19f,.26f,.36f),.08f,.36f);
    var dome=Material(owner,"TerraceThemeRoof"+chapter,chapter==0?new Color(.17f,.30f,.36f):chapter==1?new Color(.56f,.32f,.12f):new Color(.055f,.20f,.31f),.56f,.65f);
    var water=Material(owner,"TerraceCanalWater"+chapter,chapter==2?new Color(.06f,.23f,.38f):new Color(.16f,.42f,.44f),.22f,.86f);
    var lamps=Material(owner,"TerraceWindowLight"+chapter,chapter==2?new Color(.31f,.72f,.91f):new Color(.96f,.66f,.25f),.08f,.44f);lamps.SetColor("_EmissionColor",lamps.color*(chapter==2?.65f:.18f));
    var stoneBuffer=new Buffer();var roofBuffer=new Buffer();var brassBuffer=new Buffer();var foliage=new Buffer();var lightBuffer=new Buffer();var waterBuffer=new Buffer();
    // Open canal arcades surround a clear 12m radius play space. All are meshes,
    // with open arch interiors and no collision or camera changes.
    for(int bank=0;bank<2;bank++){float z=bank==0?24:-26;Marker(theme,"CanalArcade");for(int bay=0;bay<9;bay++){float x=-28+bay*7;stoneBuffer.Arch(new Vector3(x,-5.2f,z),3.3f,2.9f,2.15f,.48f,1.35f);stoneBuffer.Box(new Vector3(x,.27f,z),new Vector3(7,.65f,2.0f));for(int baluster=0;baluster<3;baluster++)stoneBuffer.Box(new Vector3(x-2.2f+baluster*2.2f,1.02f,z-1.03f),new Vector3(.15f,1.0f,.15f));stoneBuffer.Box(new Vector3(x,1.57f,z-1.03f),new Vector3(7,.15f,.24f));}waterBuffer.Box(new Vector3(0,-5.45f,z+2.0f),new Vector3(62,.08f,8));}
    for(int building=0;building<8;building++){float angle=(building*45+12)*Mathf.Deg2Rad;float radius=building%3==0?27:34;var at=new Vector3(Mathf.Cos(angle)*radius,-5.0f,Mathf.Sin(angle)*radius);float height=7+(building%4)*2.0f;
     stoneBuffer.Box(at+new Vector3(0,-.18f,0),new Vector3(8.2f,.36f,7.0f));stoneBuffer.Arch(at+new Vector3(0,-2.5f,0),2.65f,1.25f,.92f,.30f,3.6f);
     if(chapter==0)DayTower(theme,stoneBuffer,roofBuffer,brassBuffer,lightBuffer,at,height,building);
     else if(chapter==1)Palazzo(theme,stoneBuffer,roofBuffer,brassBuffer,lightBuffer,at,height,building);
     else NightTower(theme,stoneBuffer,roofBuffer,brassBuffer,lightBuffer,at,height,building);
     for(int plant=0;plant<2;plant++){var tree=at+new Vector3(-3.5f+plant*7,0,-3);Cypress(foliage,tree);}
    }
    for(int landmark=0;landmark<3;landmark++){float angle=(landmark*120+30)*Mathf.Deg2Rad;var at=new Vector3(Mathf.Cos(angle)*48,-5.5f,Mathf.Sin(angle)*48);float height=14+landmark*2;
     if(chapter==2)NightTower(theme,stoneBuffer,roofBuffer,brassBuffer,lightBuffer,at,height,landmark);else DayTower(theme,stoneBuffer,roofBuffer,brassBuffer,lightBuffer,at,height,landmark);
    }
    stoneBuffer.Upload(theme,"TerraceMasonry"+chapter,masonry,owner);roofBuffer.Upload(theme,"TerraceDomes"+chapter,dome,owner);brassBuffer.Upload(theme,"TerraceArchitecturalBrass"+chapter,brass,owner);foliage.Upload(theme,"TerraceGardens"+chapter,leaf,owner);lightBuffer.Upload(theme,"TerraceWindowBays"+chapter,lamps,owner);waterBuffer.Upload(theme,"TerraceCanal"+chapter,water,owner);
   }
   owner.Bind(themes);
  }
  static Material Material(TerraceArtOwner owner,string name,Color color,float metallic,float gloss){var shader=Resources.Load<Shader>("PerfectDropSurface");var material=new Material(shader){name=name,color=color,enableInstancing=true};material.SetFloat("_Metallic",metallic);material.SetFloat("_Glossiness",gloss);owner.Own(material);return material;}
  static void Marker(Transform parent,string name){new GameObject(name).transform.SetParent(parent,false);}
  static void Lantern(Buffer stone,Buffer gold,Vector3 at){stone.Box(at+Vector3.up*.5f,new Vector3(.63f,1,.63f));gold.Box(at+Vector3.up*1.70f,new Vector3(.06f,1.4f,.06f));gold.Box(at+Vector3.up*2.21f,new Vector3(.50f,.70f,.50f));gold.Lathe(at,new[]{2.55f,2.82f},new[]{.39f,.04f},8);}
  static void Cypress(Buffer b,Vector3 p){b.Lathe(p,new[]{.0f,.50f,1.0f,2.5f,3.2f,3.6f},new[]{.15f,.48f,.69f,.53f,.30f,.02f},10);}
  static void Windows(Buffer stone,Buffer light,Vector3 at,float height,float width){for(int floor=0;floor<Mathf.FloorToInt(height/2.3f);floor++)for(int bay=-1;bay<=1;bay++){var p=at+new Vector3(bay*width*.29f,1.6f+floor*2.3f,width*.51f);stone.Arch(p-Vector3.up*.54f,.51f,.56f,.60f,.10f,.15f);light.Box(p,new Vector3(.65f,1.2f,.04f));}}
  static void DayTower(Transform theme,Buffer stone,Buffer roof,Buffer brass,Buffer light,Vector3 at,float height,int index){Marker(theme,"DayBellTower");float width=index%3==0?5.6f:4.3f;stone.Box(at+Vector3.up*(height*.5f),new Vector3(width,height,width));Windows(stone,light,at,height,width);stone.Box(at+Vector3.up*(height+.20f),new Vector3(width+.42f,.4f,width+.42f));Marker(theme,"ArchitecturalDome");roof.Dome(at+Vector3.up*(height+.3f),width*.56f,width*.52f,20);brass.Lathe(at,new[]{height+width*.52f+.25f,height+width*.52f+1.4f},new[]{.09f,.018f},8);if(index%3==0){for(int side=-1;side<=1;side+=2)stone.Arch(at+new Vector3(side*width*.75f,0,0),2.0f,2.5f,2.0f,.28f,2.3f);}}
  static void Palazzo(Transform theme,Buffer stone,Buffer roof,Buffer brass,Buffer light,Vector3 at,float height,int index){Marker(theme,"SunsetPalazzo");float width=6.2f;stone.Box(at+Vector3.up*(height*.32f),new Vector3(width,height*.64f,5));var upper=at+new Vector3(.55f,height*.64f,-.3f);stone.Box(upper+Vector3.up*(height*.18f),new Vector3(4.2f,height*.36f,3.9f));Windows(stone,light,at,height*.64f,5);stone.Box(upper+Vector3.up*(height*.36f+.2f),new Vector3(4.7f,.4f,4.4f));Marker(theme,"ArchitecturalDome");roof.Dome(upper+Vector3.up*(height*.36f+.4f),2.35f,2.2f,20);for(int bay=-1;bay<=1;bay++)stone.Arch(at+new Vector3(bay*2.0f,-.1f,2.8f),.94f,1.17f,1.45f,.19f,.68f);brass.Ring(at+Vector3.up*(height*.64f+.04f),3.1f,.055f,24);}
  static void NightTower(Transform theme,Buffer stone,Buffer roof,Buffer brass,Buffer light,Vector3 at,float height,int index){Marker(theme,"NightCrystalSpire");stone.Box(at+Vector3.up*(height*.38f),new Vector3(4.4f,height*.76f,4.4f));stone.Box(at+Vector3.up*(height*.84f),new Vector3(3.1f,height*.20f,3.1f));roof.Lathe(at,new[]{height*.94f,height*1.05f,height*1.4f},new[]{2.35f,1.85f,.02f},6);for(int edge=-1;edge<=1;edge+=2)light.Box(at+new Vector3(edge*1.77f,height*.5f,2.23f),new Vector3(.085f,height*.84f,.05f));Windows(stone,light,at,height*.70f,4.4f);brass.Box(at+Vector3.up*(height*.76f),new Vector3(4.6f,.12f,4.6f));Marker(theme,"ArchitecturalDome");roof.Dome(at+new Vector3(-4.3f,2.7f,0),1.75f,1.1f,16);stone.Arch(at+new Vector3(-4.3f,0,0),1.5f,1.5f,1.7f,.24f,1.8f);}

  // Buffers assemble authored curved structural surfaces directly; one output
  // renderer per material replaces hundreds of independently drawn ornaments.
  public sealed class Buffer {
   readonly List<Vector3> vertices=new();readonly List<int> triangles=new();readonly List<Vector2> uv=new();
   public void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,Vector3 outward){int first=vertices.Count;vertices.AddRange(new[]{a,b,c,d});uv.AddRange(new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up});if(Vector3.Dot(Vector3.Cross(b-a,c-a),outward)>=0)triangles.AddRange(new[]{first,first+1,first+2,first,first+2,first+3});else triangles.AddRange(new[]{first,first+2,first+1,first,first+3,first+2});}
   public void Box(Vector3 at,Vector3 size){var h=size*.5f;Vector3 P(float x,float y,float z)=>at+Vector3.Scale(h,new Vector3(x,y,z));Quad(P(-1,-1,1),P(1,-1,1),P(1,1,1),P(-1,1,1),Vector3.forward);Quad(P(1,-1,-1),P(-1,-1,-1),P(-1,1,-1),P(1,1,-1),Vector3.back);Quad(P(1,-1,1),P(1,-1,-1),P(1,1,-1),P(1,1,1),Vector3.right);Quad(P(-1,-1,-1),P(-1,-1,1),P(-1,1,1),P(-1,1,-1),Vector3.left);Quad(P(-1,1,1),P(1,1,1),P(1,1,-1),P(-1,1,-1),Vector3.up);Quad(P(-1,-1,-1),P(1,-1,-1),P(1,-1,1),P(-1,-1,1),Vector3.down);}
   public void Ring(Vector3 at,float radius,float width,int sides){for(int i=0;i<sides;i++){float a=i*Mathf.PI*2/sides,b=(i+1)*Mathf.PI*2/sides;Vector3 R(float angle,float r)=>at+new Vector3(Mathf.Cos(angle)*r,0,Mathf.Sin(angle)*r);Quad(R(a,radius),R(b,radius),R(b,radius-width),R(a,radius-width),Vector3.up);}}
   public void Lathe(Vector3 at,float[] heights,float[] radii,int sides){int first=vertices.Count;for(int ring=0;ring<heights.Length;ring++)for(int side=0;side<=sides;side++){float a=side*Mathf.PI*2/sides;vertices.Add(at+new Vector3(Mathf.Cos(a)*radii[ring],heights[ring],Mathf.Sin(a)*radii[ring]));uv.Add(new Vector2((float)side/sides,(float)ring/(heights.Length-1)));}for(int ring=0;ring<heights.Length-1;ring++)for(int side=0;side<sides;side++){int a=first+ring*(sides+1)+side,b=a+sides+1;triangles.AddRange(new[]{a,b,a+1,a+1,b,b+1});}foreach(int end in new[]{0,heights.Length-1}){int center=vertices.Count;vertices.Add(at+Vector3.up*heights[end]);uv.Add(new Vector2(.5f,.5f));int start=first+end*(sides+1);for(int side=0;side<sides;side++)triangles.AddRange(end==0?new[]{start+side,start+side+1,center}:new[]{start+side,center,start+side+1});}}
   public void Dome(Vector3 at,float radius,float height,int sides){var y=new float[7];var r=new float[7];for(int ring=0;ring<7;ring++){float a=ring*Mathf.PI/12;y[ring]=Mathf.Sin(a)*height;r[ring]=Mathf.Max(.02f,Mathf.Cos(a)*radius);}Lathe(at,y,r,sides);}
   public void Arch(Vector3 at,float radius,float rise,float spring,float thickness,float depth){const int segments=12;for(int i=0;i<segments;i++){float a=i*Mathf.PI/segments,b=(i+1)*Mathf.PI/segments;Vector3 P(float angle,bool outer,float z)=>at+new Vector3(Mathf.Cos(angle)*(radius+(outer?thickness:0)),spring+Mathf.Sin(angle)*(rise+(outer?thickness:0)),z);float front=depth*.5f,back=-front;Quad(P(a,true,front),P(b,true,front),P(b,false,front),P(a,false,front),Vector3.forward);Quad(P(a,false,back),P(b,false,back),P(b,true,back),P(a,true,back),Vector3.back);Quad(P(a,true,back),P(b,true,back),P(b,true,front),P(a,true,front),new Vector3(Mathf.Cos((a+b)*.5f),Mathf.Sin((a+b)*.5f),0));Quad(P(a,false,front),P(b,false,front),P(b,false,back),P(a,false,back),new Vector3(-Mathf.Cos((a+b)*.5f),-Mathf.Sin((a+b)*.5f),0));}foreach(int side in new[]{-1,1})Box(at+new Vector3(side*(radius+thickness*.5f),spring*.5f,0),new Vector3(thickness,spring,depth));}
   public Mesh Mesh(string name){var mesh=new Mesh{name=name};if(vertices.Count>65535)mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.SetUVs(0,uv);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
   public void Upload(Transform parent,string name,Material material,TerraceArtOwner owner){if(vertices.Count==0)return;var mesh=Mesh(name);var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(parent,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=material;owner.Own(mesh);}
  }
 }
}
